DROP TABLE IF EXISTS `comment`;
CREATE TABLE `comment` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `body` longtext COLLATE utf8_unicode_ci,
  `user_id` int(11) DEFAULT NULL,
  `commentable_id` int(11) DEFAULT NULL,
  `commentable_type` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `date_added` int(11) DEFAULT NULL,
  `last_modified` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `contact`;
CREATE TABLE `contact` (
  `id` int(21) NOT NULL AUTO_INCREMENT,
  `first_name` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `last_name` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `email` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `phone` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `address` text COLLATE utf8_unicode_ci,
  `message` text COLLATE utf8_unicode_ci,
  `has_read` int(11) DEFAULT NULL,
  `replied` int(11) DEFAULT NULL,
  `created_at` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `updated_at` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `coupons`;
CREATE TABLE `coupons` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `discount_percentage` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `created_at` int(11) DEFAULT NULL,
  `expiry_date` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `course`;
CREATE TABLE `course` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `short_description` longtext COLLATE utf8_unicode_ci,
  `description` longtext COLLATE utf8_unicode_ci,
  `outcomes` longtext COLLATE utf8_unicode_ci,
  `faqs` text COLLATE utf8_unicode_ci NOT NULL,
  `language` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `category_id` int(11) DEFAULT NULL,
  `sub_category_id` int(11) DEFAULT NULL,
  `section` longtext COLLATE utf8_unicode_ci,
  `requirements` longtext COLLATE utf8_unicode_ci,
  `price` double DEFAULT NULL,
  `discount_flag` int(11) DEFAULT '0',
  `discounted_price` double DEFAULT NULL,
  `level` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `user_id` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `thumbnail` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `video_url` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `date_added` int(11) DEFAULT NULL,
  `last_modified` int(11) DEFAULT NULL,
  `course_type` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `is_top_course` int(11) DEFAULT '0',
  `is_admin` int(11) DEFAULT NULL,
  `status` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `course_overview_provider` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `meta_keywords` longtext COLLATE utf8_unicode_ci,
  `meta_description` longtext COLLATE utf8_unicode_ci,
  `is_free_course` int(11) DEFAULT NULL,
  `multi_instructor` int(11) NOT NULL DEFAULT '0',
  `enable_drip_content` int(11) NOT NULL,
  `creator` int(11) DEFAULT NULL,
  `expiry_period` int(11) DEFAULT NULL,
  `upcoming_image_thumbnail` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `publish_date` varchar(500) COLLATE utf8_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
INSERT INTO `course` (`id`, `title`, `short_description`, `description`, `outcomes`, `faqs`, `language`, `category_id`, `sub_category_id`, `section`, `requirements`, `price`, `discount_flag`, `discounted_price`, `level`, `user_id`, `thumbnail`, `video_url`, `date_added`, `last_modified`, `course_type`, `is_top_course`, `is_admin`, `status`, `course_overview_provider`, `meta_keywords`, `meta_description`, `is_free_course`, `multi_instructor`, `enable_drip_content`, `creator`, `expiry_period`, `upcoming_image_thumbnail`, `publish_date`) VALUES ('6', 'Complete Python Course', 'Python courses for further learning. I strongly recommend you not to buy any overpriced course. One of the most underrated resources in the journey of programmers is Udemy (This post is not sponsored). The affordable courses Udemy provides with doubt support are way way better than most of the paid courses I see online these days. Here are some of my top picks with discount applied for you:', '<h3><strong>Python Full Course Outline</strong></h3><h4><strong>1. Introduction to Python</strong></h4><ul><li><strong>What is Python?</strong><ul><li>Overview of Pythons history, popularity, and use cases.</li></ul></li><li><strong>Setting Up the Environment</strong><ul><li>Step-by-step installation guide for Python.</li><li>Configuring an IDE: Install VSCode/PyCharm and necessary extensions.</li></ul></li><li><strong>Hello World Program</strong><ul><li>Write and run the simplest Python program.</li></ul></li><li><strong>Basic Syntax and Structure</strong><ul><li>Discuss Pythons indentation-based syntax and basic structure.</li></ul></li></ul><h4><strong>2. Basic Python Concepts</strong></h4><ul><li><strong>Variables and Data Types</strong><ul><li>Detailed examples of each data type and their operations.</li></ul></li><li><strong>Basic Operators</strong><ul><li>Practical examples of arithmetic, comparison, and logical operations.</li></ul></li><li><strong>Control Flow</strong><ul><li>Hands-on exercises with conditional statements and loops.</li></ul></li></ul><h4><strong>3. Functions and Modules</strong></h4><ul><li><strong>Defining Functions</strong><ul><li>Practice creating functions with various parameters.</li></ul></li><li><strong>Scope and Lifetime</strong><ul><li>Exercises to illustrate local and global scope.</li></ul></li><li><strong>Lambda Functions</strong><ul><li>Simple exercises to demonstrate lambda functions.</li></ul></li><li><strong>Modules and Packages</strong><ul><li>Create custom modules and packages; practice importing and using them.</li></ul></li><li><strong>Standard Library Overview</strong><ul><li>Explore frequently used libraries such as <code>math</code>, <code>datetime</code>, etc.</li></ul></li></ul><h4><strong>4. Data Structures and Algorithms</strong></h4><ul><li><strong>Lists and List Comprehensions</strong><ul><li>Hands-on with list operations and comprehensions.</li></ul></li><li><strong>Dictionaries and Dictionary Comprehensions</strong><ul><li>Practice operations and comprehensions with dictionaries.</li></ul></li><li><strong>Sets and Frozensets</strong><ul><li>Implement exercises using sets.</li></ul></li><li><strong>Tuples and NamedTuples</strong><ul><li>Hands-on examples with tuples and namedtuples.</li></ul></li><li><strong>Queues and Stacks</strong><ul><li>Implement basic queue and stack operations.</li></ul></li><li><strong>Sorting Algorithms</strong><ul><li>Implement and compare different sorting algorithms.</li></ul></li><li><strong>Searching Algorithms</strong><ul><li>Implement linear and binary search algorithms.</li></ul></li></ul><h4><strong>5. Object-Oriented Programming (OOP)</strong></h4><ul><li><strong>Classes and Objects</strong><ul><li>Create and manipulate classes and objects.</li></ul></li><li><strong>Attributes and Methods</strong><ul><li>Practical examples of defining attributes and methods.</li></ul></li><li><strong>Inheritance</strong><ul><li>Exercises on base and derived classes.</li></ul></li><li><strong>Polymorphism</strong><ul><li>Implement polymorphism through method overriding.</li></ul></li><li><strong>Encapsulation</strong><ul><li>Practice encapsulation with private and public attributes.</li></ul></li><li><strong>Magic Methods</strong><ul><li>Use and create custom magic methods.</li></ul></li></ul><h4><strong>6. File Handling</strong></h4><ul><li><strong>Reading and Writing Files</strong><ul><li>Hands-on practice with file operations.</li></ul></li><li><strong>Working with JSON and CSV</strong><ul><li>Exercises to read from and write to JSON and CSV files.</li></ul></li><li><strong>Handling Exceptions</strong><ul><li>Practice exception handling with various scenarios.</li></ul></li></ul><h4><strong>7. Advanced Topics</strong></h4><ul><li><strong>Decorators</strong><ul><li>Implement and use decorators for modifying functions.</li></ul></li><li><strong>Generators and Iterators</strong><ul><li>Create and use generators and iterators.</li></ul></li><li><strong>Context Managers</strong><ul><li>Implement context managers using <code>with</code>.</li></ul></li><li><strong>Concurrency and Parallelism</strong><ul><li>Simple examples of threading and multiprocessing.</li></ul></li><li><strong>Asynchronous Programming</strong><ul><li>Hands-on exercises with <code>asyncio</code> and asynchronous functions.</li></ul></li></ul><h4><strong>8. Web Development with Python</strong></h4><ul><li><strong>Introduction to Web Frameworks</strong><ul><li>Choose between Flask or Django; overview of their features.</li></ul></li><li><strong>Building a Simple Web App</strong><ul><li>Create a basic web app with chosen framework.</li></ul></li><li><strong>Templates and Forms</strong><ul><li>Work with templates and forms to handle user input.</li></ul></li></ul><h4><strong>9. Data Science and Machine Learning</strong></h4><ul><li><strong>Introduction to Data Science</strong><ul><li>Overview of data science and its processes.</li></ul></li><li><strong>Libraries for Data Science</strong><ul><li>Practical exercises with NumPy, Pandas, Matplotlib, and Seaborn.</li></ul></li><li><strong>Introduction to Machine Learning</strong><ul><li>Simple ML projects using Scikit-learn; implement algorithms like linear regression and decision trees.</li></ul></li></ul><h4><strong>10. Testing and Debugging</strong></h4><ul><li><strong>Debugging Techniques</strong><ul><li>Practice using IDE debugging tools and print statements.</li></ul></li><li><strong>Unit Testing</strong><ul><li>Write and run unit tests using <code>unittest</code>.</li></ul></li><li><strong>Integration Testing</strong><ul><li>Develop and execute integration tests for larger systems.</li></ul></li></ul><h4><strong>11. Best Practices and Tools</strong></h4><ul><li><strong>Code Style and PEP 8</strong><ul><li>Learn and apply PEP 8 coding standards.</li></ul></li><li><strong>Version Control with Git</strong><ul><li>Basic Git operations: commit, push, pull, branches.</li></ul></li><li><strong>Documentation and Docstrings</strong><ul><li>Write and use docstrings for documenting code.</li></ul></li><li><strong>Project Structuring</strong><ul><li>Organize Python projects effectively.</li></ul></li></ul><h4><strong>12. Final Project</strong></h4><ul><li><strong>Project Design and Planning</strong><ul><li>Plan a comprehensive project; outline objectives and requirements.</li></ul></li><li><strong>Implementation</strong><ul><li>Develop the project using skills learned.</li></ul></li><li><strong>Testing and Debugging</strong><ul><li>Thoroughly test and debug the project.</li></ul></li><li><strong>Deployment (if applicable)</strong><ul><li>Deploy the project (e.g., deploy a web app to Heroku).</li></ul></li></ul><h3><strong>Additional Resources</strong></h3><ul><li><strong>Online Platforms:</strong> Coursera, edX, Udacity, Codecademy for supplementary learning.</li><li><strong>Books:</strong> \"Automate the Boring Stuff with Python\" by Al Sweigart, \"Python Crash Course\" by Eric Matthes for further reading.</li><li><strong>Documentation:</strong> Use official Python documentation and Real Python tutorials for in-depth learning.</li></ul><h3><strong>Practical Exercises and Projects</strong></h3><ul><li><strong>Implement simple scripts for automation</strong><ul><li>Create scripts to automate tasks like file renaming or data scraping.</li></ul></li><li><strong>Develop a basic web app</strong><ul><li>Build and deploy a web application to practice Flask or Django.</li></ul></li><li><strong>Create a data analysis project</strong><ul><li>Analyze real-world datasets using Pandas and visualization tools.</li></ul></li><li><strong>Work on machine learning problems</strong><ul><li>Solve machine learning problems using datasets and Scikit-learn.</li></ul></li></ul>', '[]', '[]', 'english', '8', '1', '[3]', '[]', '500', '1', '199', 'advanced', '11,9', NULL, 'https://www.youtube.com/watch?v=UrsmFxEIp5k', '1721944800', '1722868959', 'general', '0', '0', 'upcoming', 'youtube', '', '', NULL, '1', '1', NULL, '1', '1f05e7e42d4dec59cc0e5e279dec7d9d.jpg', '2024-08-10T17:32'), ('7', 'Data Structure using Java', '', '', '[]', '[]', 'english', '8', '1', '[7]', '[]', '399', NULL, '0', 'beginner', '3,4', NULL, 'https://youtube.com/playlist?list=PL9gnSGHSqcnr_DxHsP7AW9ftq0AtAyYqJ&si=G44aiQ3YOnWb0pXH', '1722796200', '1722860068', 'general', '0', '0', 'active', 'youtube', '', '', NULL, '1', '0', '5', NULL, NULL, ''), ('8', 'MERN', 'The MERN stack is a popular full-stack JavaScript framework for building dynamic web applications. It consists of four key technologies: MongoDB for the database, Express.js for the backend web framework, React.js for the frontend user interface, and Node.js for the server environment. Together, these technologies enable developers to build robust, scalable, and maintainable applications with a unified JavaScript codebase across both client and server sides.', '', '[]', '[]', 'english', '10', '9', '[9,11,12]', '[]', '5999', '1', '99', 'beginner', '4', NULL, '', '1722796200', '1722874523', 'general', '1', '0', 'active', '', '', '', NULL, '0', '1', '4', '1', 'c14f32ee9cf599b56eedb034f70b0534.jpg', '2024-08-10T18:44'), ('9', 'HTML,CSS&JAVASCRIPT', '', '', '[]', '[]', 'english', '10', '9', '[10,13]', '[]', '199', NULL, '99', 'beginner', '3,11', NULL, 'https://www.youtube.com/playlist?list=PLu71SKxNbfoDBNF5s-WH6aLbthSEIMhMI', '1722796200', '1722864058', 'general', '0', '0', 'active', 'youtube', '', '', NULL, '1', '0', '3', '1', NULL, '');
DROP TABLE IF EXISTS `currency`;
CREATE TABLE `currency` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) DEFAULT NULL,
  `code` varchar(255) DEFAULT NULL,
  `symbol` varchar(255) DEFAULT NULL,
  `paypal_supported` int(11) DEFAULT NULL,
  `stripe_supported` int(11) DEFAULT NULL,
  `ccavenue_supported` int(11) DEFAULT '0',
  `iyzico_supported` int(11) DEFAULT '0',
  `paystack_supported` int(11) DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=165 DEFAULT CHARSET=utf8;
