DROP TABLE IF EXISTS `custom_page`;
CREATE TABLE `custom_page` (
  `custom_page_id` int(11) NOT NULL AUTO_INCREMENT,
  `page_title` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `page_content` longtext COLLATE utf8_unicode_ci NOT NULL,
  `page_url` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `button_title` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `button_position` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `status` int(11) NOT NULL,
  PRIMARY KEY (`custom_page_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
INSERT INTO `custom_page` (`custom_page_id`, `page_title`, `page_content`, `page_url`, `button_title`, `button_position`, `status`) VALUES ('1', 'Gyantech Club', '\r\n\r\n\r\n    &lt;meta charset=&quot;UTF-8&quot;&gt;\r\n    &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt;\r\n    &lt;title&gt;Gyantech Society&lt;/title&gt;\r\n    &lt;style&gt;\r\n        body {\r\n            font-family: Arial, sans-serif;\r\n            line-height: 1.6;\r\n            margin: 0;\r\n            padding: 0;\r\n        }\r\n\r\n        header {\r\n            background-color: #4CAF50;\r\n            color: white;\r\n            padding: 10px 0;\r\n            text-align: center;\r\n        }\r\n\r\n        nav {\r\n            display: flex;\r\n            justify-content: center;\r\n            background-color: #333;\r\n        }\r\n\r\n        nav a {\r\n            color: white;\r\n            padding: 14px 20px;\r\n            text-decoration: none;\r\n            text-align: center;\r\n        }\r\n\r\n        nav a:hover {\r\n            background-color: #575757;\r\n        }\r\n\r\n        .container {\r\n            padding: 20px;\r\n            max-width: 1000px;\r\n            margin: auto;\r\n        }\r\n\r\n        .hero {\r\n            background-color: #f4f4f4;\r\n            padding: 20px;\r\n            text-align: center;\r\n        }\r\n\r\n        .section {\r\n            margin-bottom: 40px;\r\n        }\r\n\r\n        .section h2 {\r\n            border-bottom: 2px solid #4CAF50;\r\n            padding-bottom: 10px;\r\n            margin-bottom: 20px;\r\n        }\r\n\r\n        footer {\r\n            background-color: #333;\r\n            color: white;\r\n            text-align: center;\r\n            padding: 10px 0;\r\n            position: fixed;\r\n            bottom: 0;\r\n            width: 100%;\r\n        }\r\n    &lt;/style&gt;\r\n\r\n\r\n    &lt;header&gt;\r\n        &lt;h1&gt;Welcome to the Gyantech Society&lt;/h1&gt;\r\n    &lt;/header&gt;\r\n\r\n    &lt;nav&gt;\r\n        &lt;a href=&quot;#about&quot;&gt;About Us&lt;/a&gt;\r\n        &lt;a href=&quot;#events&quot;&gt;Events&lt;/a&gt;\r\n        &lt;a href=&quot;#membership&quot;&gt;Membership&lt;/a&gt;\r\n        &lt;a href=&quot;#contact&quot;&gt;Contact&lt;/a&gt;\r\n    &lt;/nav&gt;\r\n\r\n    &lt;div class=&quot;container&quot;&gt;\r\n        &lt;div class=&quot;hero&quot;&gt;\r\n            &lt;p&gt;Join us in fostering a community of learning, innovation, and growth.&lt;/p&gt;\r\n        &lt;/div&gt;\r\n\r\n        &lt;div class=&quot;section&quot; id=&quot;about&quot;&gt;\r\n            &lt;h2&gt;About Us&lt;/h2&gt;\r\n            &lt;p&gt;The Gyantech Society is dedicated to empowering individuals through education and collaboration. We aim to create a vibrant community where members can explore new interests, develop skills, and connect with like-minded individuals.&lt;/p&gt;\r\n        &lt;/div&gt;\r\n\r\n        &lt;div class=&quot;section&quot; id=&quot;events&quot;&gt;\r\n            &lt;h2&gt;Upcoming Events&lt;/h2&gt;\r\n            &lt;ul&gt;\r\n                &lt;li&gt;August 20, 2024: Workshop on AI and Machine Learning&lt;/li&gt;\r\n                &lt;li&gt;September 10, 2024: Networking Event for Tech Enthusiasts&lt;/li&gt;\r\n                &lt;li&gt;October 15, 2024: Annual Conference on Innovation in Education&lt;/li&gt;\r\n            &lt;/ul&gt;\r\n        &lt;/div&gt;\r\n\r\n        &lt;div class=&quot;section&quot; id=&quot;membership&quot;&gt;\r\n            &lt;h2&gt;Membership&lt;/h2&gt;\r\n            &lt;p&gt;Become a member to gain access to exclusive events, resources, and a supportive network. Join us today and be part of a community that values growth and collaboration.&lt;/p&gt;\r\n        &lt;/div&gt;\r\n\r\n        &lt;div class=&quot;section&quot; id=&quot;contact&quot;&gt;\r\n            &lt;h2&gt;Contact Us&lt;/h2&gt;\r\n            &lt;p&gt;If you have any questions or want to learn more about the Gyantech Society, feel free to reach out.&lt;/p&gt;\r\n            &lt;p&gt;Email: &lt;a href=&quot;mailto:info@gyantechsociety.com&quot;&gt;info@gyantechsociety.com&lt;/a&gt;&lt;/p&gt;\r\n        &lt;/div&gt;\r\n    &lt;/div&gt;\r\n\r\n    &lt;footer&gt;\r\n        &lt;p&gt; 2024 Gyantech Society. All rights reserved.&lt;/p&gt;\r\n    &lt;/footer&gt;\r\n\r\n\r\n', 'gt-club-html', 'Gyantech Club', 'footer', '1');
DROP TABLE IF EXISTS `enrol`;
CREATE TABLE `enrol` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL,
  `course_id` int(11) DEFAULT NULL,
  `gifted_by` int(11) NOT NULL DEFAULT '0',
  `expiry_date` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `date_added` int(11) DEFAULT NULL,
  `last_modified` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
INSERT INTO `enrol` (`id`, `user_id`, `course_id`, `gifted_by`, `expiry_date`, `date_added`, `last_modified`) VALUES ('1', '8', '2', '0', NULL, '1701126000', NULL), ('2', '3', '2', '0', NULL, '1701126000', NULL), ('3', '10', '3', '0', NULL, '1721858400', NULL), ('7', '7', '7', '0', NULL, '1722796200', NULL), ('8', '7', '8', '0', '1725466817', '1722796200', NULL);
DROP TABLE IF EXISTS `frontend_settings`;
CREATE TABLE `frontend_settings` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `key` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,
  `value` longtext COLLATE utf8_unicode_ci,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
INSERT INTO `frontend_settings` (`id`, `key`, `value`) VALUES ('1', 'banner_title', 'Gyantech Learning Platform'), ('2', 'banner_sub_title', 'Empower Your Future  Powered by Workboat Media Pvt Ltd. Study any topic, anytime. Explore thousands of courses for the lowest price ever! '), ('4', 'about_us', '<p></p><h4><span style=\"font-weight: normal;\"><span style=\"color: rgb(0, 0, 0);\">Welcome to the Gyantech Learning Platform<br></span><span style=\"color: rgb(0, 0, 0);\">At Gyantech, we empower learners worldwide with high-quality, accessible, and affordable education. Our mission is to support personal and professional growth by providing courses tailored to diverse needs. Join us in fostering curiosity, creativity, and lifelong learning as you advance your career and explore new interests.</span></span></h4>'), ('10', 'terms_and_condition', '<h4><span style=\"color: rgb(0, 0, 0); font-weight: normal;\">Terms and Conditions</span></h4><h2><h4 style=\"font-size: 14px;\"><h4 style=\"\"><span style=\"font-weight: normal;\"><span style=\"color: rgb(0, 0, 0);\">TERMS OF SERVICE<br></span><span style=\"color: rgb(0, 0, 0);\">Introduction<br></span><span style=\"color: rgb(0, 0, 0);\">This website is operated by Gyantech Learning Platform (the \"Website\"). Throughout the site, the terms we, us and our refer to Gyantech Learning Platform. Gyantech Learning Platform offers this website, including all information, tools, and services available from this site to you, the user, conditioned upon your acceptance of all terms, conditions, policies, and notices stated here.<br></span><span style=\"color: rgb(0, 0, 0);\">By visiting our site or purchasing something from us, you engage in our Service and agree to be bound by the following Terms of Service including those additional terms and conditions and policies referenced here or available by hyperlink. These Terms of Service apply to all users of the site, including without limitation users who are browsers, vendors, customers, merchants, or contributors of content.<br></span><span style=\"color: rgb(0, 0, 0);\">Please read these Terms of Service carefully before accessing or using our website. By accessing or using any part of the site, you agree to be bound by these Terms of Service. If you do not agree to all the terms and conditions of this agreement, then you may not access the website or use any services. If these Terms of Service are considered an offer, acceptance is expressly limited to these Terms of Service.<br></span><span style=\"color: rgb(0, 0, 0);\">Any new features or tools which are added to the current store shall also be subject to the Terms of Service. You can review the most current version of the Terms of Service at any time on this page. We reserve the right to update, change, or replace any part of these Terms of Service by posting updates and changes to our website. It is your responsibility to check this page periodically for changes. Your continued use of or access to the website following the posting of any changes constitutes acceptance of those changes.<br></span><span style=\"color: rgb(0, 0, 0);\">SECTION 1 - ONLINE STORE TERMS<br></span><span style=\"color: rgb(0, 0, 0);\">By agreeing to these Terms of Service, you represent that you are at least the age of majority in your state or province of residence, or that you are the age of majority in your state or province of residence and you have given us your consent to allow any of your minor dependents to use this site. You may not use our products for any illegal or unauthorized purpose nor may you, in the use of the Service, violate any laws in your jurisdiction (including but not limited to copyright laws). You must not transmit any worms or viruses or any code of a destructive nature. A breach or violation of any of the Terms will result in an immediate termination of your Services.<br></span><span style=\"color: rgb(0, 0, 0);\">SECTION 2 - GENERAL CONDITIONS<br></span><span style=\"color: rgb(0, 0, 0);\">We reserve the right to refuse service to anyone for any reason at any time. You understand that your content (not including credit card information) may be transferred unencrypted and involve (a) transmissions over various networks; and (b) changes to conform and adapt to technical requirements of connecting networks or devices. Credit card information is always encrypted during transfer over networks. You agree not to reproduce, duplicate, copy, sell, resell or exploit any portion of the Service, use of the Service, or access to the Service or any contact on the website through which the service is provided, without express written permission by us. The headings used in this agreement are included for convenience only and will not limit or otherwise affect these Terms.<br></span><span style=\"color: rgb(0, 0, 0);\">SECTION 3 - ACCURACY, COMPLETENESS, AND TIMELINESS OF INFORMATION<br></span><span style=\"color: rgb(0, 0, 0);\">We are not responsible if information made available on this site is not accurate, complete, or current. The material on this site is provided for general information only and should not be relied upon or used as the sole basis for making decisions without consulting primary, more accurate, more complete, or more timely sources of information. Any reliance on the material on this site is at your own risk. This site may contain certain historical information. Historical information, necessarily, is not current and is provided for your reference only. We reserve the right to modify the contents of this site at any time, but we have no obligation to update any information on our site. You agree that it is your responsibility to monitor changes to our site.<br></span><span style=\"color: rgb(0, 0, 0);\">SECTION 4 - MODIFICATIONS TO THE SERVICE AND PRICES<br></span><span style=\"color: rgb(0, 0, 0);\">Prices for our products are subject to change without notice. We reserve the right at any time to modify or discontinue the Service (or any part or content thereof) without notice at any time. We shall not be liable to you or to any third-party for any modification, price change, suspension, or discontinuance of the Service.<br></span><span style=\"color: rgb(0, 0, 0);\">SECTION 5 - PRODUCTS OR SERVICES<br></span><span style=\"color: rgb(0, 0, 0);\">Certain products or services may be available exclusively online through the website. These products or services may have limited quantities and are subject to return or exchange only according to our Return Policy. We have made every effort to display as accurately as possible the colors and images of our products that appear at the store. We cannot guarantee that your computer monitor\'s display of any color will be accurate.<br></span><span style=\"color: rgb(0, 0, 0);\">We reserve the right, but are not obligated, to limit the sales of our products or Services to any person, geographic region, or jurisdiction. We may exercise this right on a case-by-case basis. We reserve the right to limit the quantities of any products or services that we offer. All descriptions of products or product pricing are subject to change at any time without notice, at our sole discretion. We reserve the right to discontinue any product at any time. Any offer for any product or service made on this site is void where prohibited.<br></span><span style=\"color: rgb(0, 0, 0);\">We do not warrant that the quality of any products, services, information, or other material purchased or obtained by you will meet your expectations, or that any errors in the Service will be corrected.<br></span><span style=\"color: rgb(0, 0, 0);\">SECTION 6 - ACCURACY OF BILLING AND ACCOUNT INFORMATION<br></span><span style=\"color: rgb(0, 0, 0);\">We reserve the right to refuse any order you place with us. We may, in our sole discretion, limit or cancel quantities purchased per person, per household, or per order. These restrictions may include orders placed by or under the same customer account, the same credit card, and/or orders that use the same billing and shipping address. In the event that we make a change to or cancel an order, we may attempt to notify you by contacting the e-mail and/or billing address/phone number provided at the time the order was made. We reserve the right to limit or prohibit orders that, in our sole judgment, appear to be placed by dealers, resellers, or distributors.<br></span><span style=\"color: rgb(0, 0, 0);\">You agree to provide current, complete, and accurate purchase and account information for all purchases made at our store. You agree to promptly update your account and other information, including your email address and credit card numbers and expiration dates, so that we can complete your transactions and contact you as needed. For more detail, please review our Returns Policy.<br></span><span style=\"color: rgb(0, 0, 0);\">SECTION 7 - OPTIONAL TOOLS<br></span><span style=\"color: rgb(0, 0, 0);\">We may provide you with access to third-party tools over which we neither monitor nor have any control nor input. You acknowledge and agree that we provide access to such tools as is and as available without any warranties, representations, or conditions of any kind and without any endorsement. We shall have no liability whatsoever arising from or relating to your use of optional third-party tools. Any use by you of optional tools offered through the site is entirely at your own risk and discretion and you should ensure that you are familiar with and approve of the terms on which tools are provided by the relevant third-party provider(s).<br></span><span style=\"color: rgb(0, 0, 0);\">We may also, in the future, offer new services and/or features through the website (including the release of new tools and resources). Such new features and/or services shall also be subject to these Terms of Service.<br></span><span style=\"color: rgb(0, 0, 0);\">SECTION 8 - THIRD-PARTY LINKS<br></span><span style=\"color: rgb(0, 0, 0);\">Certain content, products, and services available via our Service may include materials from third parties. Third-party links on this site may direct you to third-party websites that are not affiliated with us. We are not responsible for examining or evaluating the content or accuracy, and we do not warrant and will not have any liability or responsibility for any third-party materials or websites, or for any other materials, products, or services of third-parties.<br></span><span style=\"color: rgb(0, 0, 0);\">We are not liable for any harm or damages related to the purchase or use of goods, services, resources, content, or any other transactions made in connection with any third-party websites. Please review carefully the third-party\'s policies and practices and make sure you understand them before you engage in any transaction. Complaints, claims, concerns, or questions regarding third-party products should be directed to the third-party.<br></span><span style=\"color: rgb(0, 0, 0);\">SECTION 9 - USER COMMENTS, FEEDBACK, AND OTHER SUBMISSIONS<br></span><span style=\"color: rgb(0, 0, 0);\">You will not use any unethical practices to complete your course which includes copying the assignments, cheating in the tests, etc. If you are found to use any unethical practices, the mentor has the right to take your live test, give additional projects, or even deny you any certification and ban your account.<br></span><span style=\"color: rgb(0, 0, 0);\">SECTION 10 - PERSONAL INFORMATION<br></span><span style=\"color: rgb(0, 0, 0);\">Your submission of personal information through the store is governed by our Privacy Policy.<br></span><span style=\"color: rgb(0, 0, 0);\">SECTION 11 - ERRORS, INACCURACIES, AND OMISSIONS<br></span><span style=\"color: rgb(0, 0, 0);\">Occasionally there may be information on our site or in the Service that contains typographical errors, inaccuracies, or omissions that may relate to product descriptions, pricing, promotions, offers, product shipping charges, transit times, and availability. We reserve the right to correct any errors, inaccuracies, or omissions, and to change or update information or cancel orders if any information in the Service or on any related website is inaccurate at any time without prior notice (including after you have submitted your order).<br></span><span style=\"color: rgb(0, 0, 0);\">We undertake no obligation to update, amend or clarify information in the Service or on any related website, including without limitation, pricing information, except as required by law. No specified update or refresh date applied in the Service or on any related website, should be taken to indicate that all information in the Service or on any related website has been modified or updated.<br></span><span style=\"color: rgb(0, 0, 0);\">SECTION 12 - PROHIBITED USES<br></span><span style=\"color: rgb(0, 0, 0);\">In addition to other prohibitions as set forth in the Terms of Service, you are prohibited from using the site or its content: (a) for any unlawful purpose; (b) to solicit</span></span></h4></h4></h2>'), ('11', 'privacy_policy', '<p></p><p></p><h3><h4 class=\"dropdown-item\"><h4><span style=\"color: rgb(0, 0, 0); font-weight: normal;\">Privacy Policy for Gyantech E-Learning Platform<br>SECTION 1 - INFORMATION WE COLLECT<br>When you register or use our platform, we collect personal information such as your name, email address, and contact details. We may also collect information about your interactions with the platform, including course enrollment and completion data.<br>SECTION 2 - CONSENT<br>How do we obtain your consent?<br>By providing us with personal information during registration or using our platform, you consent to our collection and use of this information for providing services. For secondary purposes like marketing, we will ask for your explicit consent.<br>How do I withdraw my consent?<br>You can withdraw your consent at any time by contacting us at <a rel=\"noreferrer\">support@gyantech.online</a>.<br>SECTION 3 - USE OF INFORMATION<br>We use your personal information to provide and improve our services, process transactions, communicate with you, and send updates about new courses or features.<br>SECTION 4 - DISCLOSURE<br>We may disclose your information if required by law or if you violate our Terms of Service.<br>SECTION 5 - THIRD-PARTY SERVICES<br>Third-party providers we use will only collect, use, and disclose your information to the extent necessary to perform services for us. We encourage you to review their privacy policies to understand how they handle your data.<br>SECTION 6 - SECURITY<br>We take reasonable precautions to protect your personal information. Your data is secured and only accessible by authorized personnel.<br>SECTION 7 - COOKIES<br>We use cookies to enhance user experience and analyze platform traffic. Cookies do not contain personally identifiable information.<br>SECTION 8 - AGE OF CONSENT<br>By using this site, you confirm that you are at least the age of majority in your state or province of residence, or you have consent from your guardian to use the platform.<br>SECTION 9 - CHANGES TO THIS PRIVACY POLICY<br>We reserve the right to update this policy. Changes will take effect immediately upon posting on the website. We will notify you of significant changes to this policy.<br>QUESTIONS AND CONTACT INFORMATION<br>If you have questions, want to access, correct, or delete your information, or have any concerns, please contact our Privacy Compliance Officer at <a rel=\"noreferrer\">support@gyantech.online</a>.</span></h4></h4></h3>'), ('13', 'theme', 'default-new'), ('14', 'cookie_note', 'Cookie Notice\r\nWelcome to Gyantech Learning Platform\r\nWe use cookies to enhance your experience on our website. By continuing to browse, you agree to our use of cookies. Cookies help us improve our services, personalize your experience, and provide you with relevant content and ads. \r\nTo learn more about how we use cookies and how you can manage them, please read our [Cookie Policy](#).\r\nThank you for visiting Gyantech Learning Platform!\r\n*Powered by Workboat Media Pvt Ltd*'), ('15', 'cookie_status', 'inactive'), ('16', 'cookie_policy', '<h1><span style=\"color: rgb(0, 0, 0);\">Cookie Policy</span></h1><ol><li><span style=\"color: rgb(0, 0, 0);\">Cookies are small text files that can be used by websites to make a user\'s experience more efficient.</span></li><li><span style=\"color: rgb(0, 0, 0);\">The law states that we can store cookies on your device if they are strictly necessary for the operation of this site. For all other types of cookies, we need your permission.</span></li><li><span style=\"color: rgb(0, 0, 0);\">This site uses different types of cookies. Some cookies are placed by third-party services that appear on our pages.</span></li></ol>'), ('17', 'banner_image', '{\"home_1\":\"974c7c43927ff8e3b61adb8b3d0841a8.png\"}'), ('18', 'light_logo', 'c9d9edbf9b9e23eb5d4819bbcce9b078.png'), ('19', 'dark_logo', 'e58f87416d6ed5ba171e7aa2424b0448.png'), ('20', 'small_logo', '319b2600b8defbf79afcb125d55ff9c7.png'), ('21', 'favicon', 'ecac401b672c0e65661d7c759900149a.png'), ('22', 'recaptcha_status', '1'), ('23', 'recaptcha_secretkey', '6Ld8hBgqAAAAABakL1zVCTNCrrxoMwPXB6wXwAPY'), ('24', 'recaptcha_sitekey', '6Ld8hBgqAAAAABN9yS7XHXXSyCR1VQbP2vis9oIC'), ('25', 'refund_policy', '<h2><span xss=\"removed\" style=\"font-weight: normal; color: rgb(66, 66, 66);\">Refund Policy</span></h2><h2><span xss=\"removed\" style=\"font-weight: normal; color: rgb(66, 66, 66);\"><h4 style=\"\">Refund Policy for Gyantech E-Learning Platform<br>SECTION 1 - GENERAL POLICY<br>We strive to provide quality educational content and services. However, if you are not satisfied with a course or service, you may be eligible for a refund under certain conditions.<br>SECTION 2 - ELIGIBILITY FOR REFUNDS<br>Full Courses: Refunds for full courses are available within 14 days of purchase, provided that no more than 20% of the course content has been accessed or completed.<br>Subscription Services: If you have subscribed to a service, you can request a refund within the first 14 days of the initial subscription, provided you have not accessed or completed more than 20% of the content.<br>Course Bundles: Refunds for course bundles are considered individually, with the same conditions applied to each course within the bundle.<br>Promotional and Discounted Courses: Courses purchased at a discount or through a promotion are non-refundable unless stated otherwise in the promotion terms.<br>SECTION 3 - NON-REFUNDABLE ITEMS<br>Certificates: Fees for certificates or accreditation are non-refundable once issued.<br>Digital Content: Standalone digital content like e-books or downloadable resources is non-refundable.<br>SECTION 4 - HOW TO REQUEST A REFUND<br>Contact Us: To initiate a refund request, contact our support team at <a rel=\"noreferrer\" style=\"\">support@gyantech.online</a> with your order details and reason for the refund request.<br>Review Process: Once your request is received, we will review it and notify you of the approval or rejection of your refund.<br>Refund Method: Approved refunds will be processed back to the original payment method within 5-10 business days.<br>SECTION 5 - CANCELLATION POLICY<br>Subscription Cancellation: You can cancel your subscription at any time. Access will continue until the end of the current billing cycle, but no further charges will be incurred.<br>Course Enrollment Cancellation: You can cancel course enrollment at any time, but refunds are only provided under the conditions stated in the eligibility section.<br>SECTION 6 - CHANGES TO THIS POLICY<br>We reserve the right to modify this refund policy at any time. Changes will be effective immediately upon posting on the website. We encourage you to review this policy periodically for any updates.<br>QUESTIONS AND CONTACT INFORMATION<br>For any questions or more information about our refund policy, please contact us at <a rel=\"noreferrer\" style=\"\">support@gyantech.online</a>.</h4></span></h2>'), ('26', 'facebook', 'https://facebook.com'), ('27', 'twitter', 'https://twitter.com'), ('28', 'linkedin', ''), ('31', 'blog_page_title', 'Where possibilities begin'), ('32', 'blog_page_subtitle', 'Were a leading marketplace platform for learning and teaching online. Explore some of our most popular content and learn something new.'), ('33', 'blog_page_banner', 'blog-page.png'), ('34', 'instructors_blog_permission', '0'), ('35', 'blog_visibility_on_the_home_page', '0'), ('37', 'website_faqs', '[]'), ('38', 'motivational_speech', '[]'), ('39', 'home_page', 'home_2'), ('40', 'contact_info', '{\"email\":\"admin@gyantech.online,\\r\\nsystem@gyantech.online\",\"phone\":\"7607777883,\\r\\n8368092473,\\r\\n8851284400\",\"address\":\"100, Ledhupur Baluaroad ashapur Sarnath Varanasi\",\"office_hours\":\"24\\/7\"}'), ('41', 'custom_css', ''), ('42', 'embed_code', ''), ('43', 'top_course_section', '1'), ('44', 'latest_course_section', '1'), ('45', 'top_category_section', '1'), ('46', 'upcoming_course_section', '1'), ('47', 'faq_section', '1'), ('48', 'top_instructor_section', '1'), ('49', 'motivational_speech_section', '0'), ('50', 'promotional_section', '1');
