) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
INSERT INTO `message_thread` (`message_thread_id`, `message_thread_code`, `sender`, `receiver`, `last_message_timestamp`) VALUES ('1', 'e32857ec309db98', '11', '12', NULL), ('2', '9tWkHTLM4YgPriNZqfCluncm3xjBa7', '7', '2', NULL);
DROP TABLE IF EXISTS `newsletter_histories`;
CREATE TABLE `newsletter_histories` (
